// Built-in preview skeletons and skins, generated by build.rs from assets/preview when it is present (release builds).
// A build from the public source has none: FILES is empty and the viewer uses the user's own skeletons.
include!(concat!(env!("OUT_DIR"), "/builtin_files.rs"));

pub fn bytes(path: &str) -> Option<&'static [u8]> {
    FILES.iter().find(|(name, _)| *name == path).map(|(_, bytes)| *bytes)
}
